def to_megabits(megabytes):
    return megabytes * 8

def download_minutes(megabytes, speed_mbps):
    return to_megabits(megabytes) / speed_mbps / 60

def hex_byte(number):
    return f"{number:02X}"

def to_codes(text):
    return [ord(c) for c in text]

def from_codes(codes):
    return "".join(chr(n) for n in codes)

def utf8_size(text):
    return len(text.encode("utf-8"))

def image_bytes(width, height, bytes_per_pixel=3):
    return width * height * bytes_per_pixel

def shrink_size(width, height, factor):
    return (width // factor, height // factor)

def audio_bytes(seconds, rate, bits, channels):
    return seconds * rate * (bits // 8) * channels

def video_mb(bitrate_mbps, minutes):
    return bitrate_mbps * minutes * 60 / 8

def decode(encoded):
    out = ""
    for i in range(0, len(encoded), 2):
        out = out + encoded[i + 1] * int(encoded[i])
    return out

def ratio(original, compressed):
    return original / compressed

def half_adder(a, b):
    return (a ^ b, a & b)

def full_adder(a, b, carry_in):
    return (a ^ b ^ carry_in, (a & b) | (carry_in & (a ^ b)))

def run(memory):
    pc = 0
    a = 0
    while True:
        op, addr = memory[pc]
        pc = pc + 1
        if op == "LOAD":
            a = memory[addr]
        elif op == "ADD":
            a = a + memory[addr]
        elif op == "SUB":
            a = a - memory[addr]
        elif op == "STORE":
            memory[addr] = a
        elif op == "HALT":
            return memory

def average_time(hit_rate, cache_time, miss_time):
    return hit_rate * cache_time + (1 - hit_rate) * miss_time

def run_cache(requests, size):
    cache = []
    hits = 0
    for item in requests:
        if item in cache:
            hits = hits + 1
            cache.remove(item)
            cache.append(item)
        else:
            cache.append(item)
            if len(cache) > size:
                cache.pop(0)
    return hits
